// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {demo} from "../src/demo.sol";

contract MockToken {
    bytes4 public lastCalledSelector;

    function transferFrom(address, address, uint256) external returns (bool) {
        lastCalledSelector = bytes4(keccak256("transferFrom(address,address,uint256)"));
        return true;
    }

    function transfer(address, uint256) external returns (bool) {
        lastCalledSelector = bytes4(keccak256("transfer(address,uint256)"));
        return true;
    }

    function transfer(address, address, uint256) external returns (bool) {
        lastCalledSelector = bytes4(keccak256("transfer(address,address,uint256)"));
        return true;
    }
}

contract InvMutTest is Test {
    demo c;
    MockToken mock;

    function setUp() public { 
        c = new demo();
        mock = new MockToken();
    }

    function testRegression_property() public {
        address[] memory tos = new address[](1);
        tos[0] = address(0x123);
        address from = address(0x456);

        c.transfer(from, address(mock), tos, 100);

        assertTrue(mock.lastCalledSelector() == bytes4(keccak256("transferFrom(address,address,uint256)")));
    }
}
